def game_of_life(grid: list[list[int]]) -> list[list[int]]:
    rows, cols = len(grid), len(grid[0])
    result = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            live = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (dr, dc) != (0, 0) and 0 <= nr < rows and 0 <= nc < cols:
                        live += grid[nr][nc]
            if live == 3 or (grid[r][c] == 1 and live == 2):
                result[r][c] = 1
    return result


rows, _ = map(int, input().split())
grid = [list(map(int, input().split())) for _ in range(rows)]
for row in game_of_life(grid):
    print(" ".join(map(str, row)))

