const tokens = require("fs").readFileSync(0, "utf8").trim().split(/\s+/).map(Number);

function gameOfLife(grid) {
  // A spot off the grid reads as undefined, so it counts as a dead cell.
  const at = (r, c) => grid[r]?.[c] ?? 0;
  return grid.map((row, r) =>
    row.map((cell, c) => {
      let live = 0;
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          if (dr !== 0 || dc !== 0) {
            live += at(r + dr, c + dc);
          }
        }
      }
      return live === 3 || (cell === 1 && live === 2) ? 1 : 0;
    })
  );
}

